  UPDATE OUTPUT    /* QueryID : com.demo.proworks.out.updateOut */      
	  SET  
       PJT_ID           = #{pjtId} 
       , NAME             = #{name} 
       , CREATED_AT       = #{createdAt} 
       , UPDATED_AT       = #{updatedAt} 
       , APPROVAL_STATUS  = #{approvalStatus} 
       , APPROVAL_DATE    = #{approvalDate} 
       , APPROVAL_COMMENT = #{approvalComment} 
       , OUTPUT_TYPE      = #{outputType} 
       , IS_DELETED       = #{isDeleted}                  
  WHERE   
      ID = #{id}

mapper.select:
SELECT /* QueryID : com.demo.proworks.out.selectListOut */ ID as id, PJT_ID as pjtId, PJT_NAME as pjtName, NAME as name, CREATED_AT as createdAt, UPDATED_AT as updatedAt, APPROVAL_STATUS as approvalStatus, APPROVAL_DATE as approvalDate, APPROVAL_COMMENT as approvalComment, OUTPUT_TYPE as outputType, IS_DELETED as isDeleted FROM ( SELECT S.*, CEIL( (@ROWNUM:=@ROWNUM+1) / #{pageSize} ) AS PAGE FROM ( SELECT o.ID, o.PJT_ID, o.NAME, o.CREATED_AT, o.UPDATED_AT, o.APPROVAL_STATUS, o.APPROVAL_DATE, o.APPROVAL_COMMENT, o.OUTPUT_TYPE, o.IS_DELETED, pjt.PJT_NAME as PJT_NAME FROM OUTPUT o LEFT JOIN PJT pjt ON o.PJT_ID = pjt.PJT_ID WHERE 1=1
AND o.PJT_ID = #{pjtId}
AND o.NAME LIKE CONCAT('%', #{name}, '%')
AND o.OUTPUT_TYPE = #{outputType}
AND o.APPROVAL_STATUS = #{approvalStatus}
AND (o.IS_DELETED IS NULL OR o.IS_DELETED = 'N') ORDER BY o.CREATED_AT DESC ) S, (SELECT @ROWNUM := 0) TMP ) A WHERE PAGE = #{pageIndex}



SELECT /* QueryID : com.demo.proworks.out.selectListCountOut */
    COUNT(*) totcnt  		                  
FROM OUTPUT o
LEFT JOIN PJT pjt ON o.PJT_ID = pjt.PJT_ID
WHERE 1=1


AND o.PJT_ID = #{pjtId}



AND o.NAME LIKE CONCAT('%', #{name}, '%')



AND o.OUTPUT_TYPE = #{outputType}



